from math import ceil


def page_key(tokens, start, page_size):
    end = min(start + page_size, len(tokens))
    return (tuple(tokens[:start]), tuple(tokens[start:end]))


def pages_of(tokens, page_size):
    if page_size <= 0:
        raise ValueError('page_size must be positive')
    return {page_key(tokens, start, page_size)
            for start in range(0, len(tokens), page_size)}


def unique_pages(seqs, page_size):
    result = set()
    for tokens in seqs:
        result.update(pages_of(tokens, page_size))
    return result


def naive_page_sum(seqs, page_size):
    if page_size <= 0:
        raise ValueError('page_size must be positive')
    return sum((len(tokens) + page_size - 1) // page_size for tokens in seqs)


def try_admit(live, candidate, capacity_pages, page_size, guard_pages=0):
    if capacity_pages < 0 or guard_pages < 0:
        raise ValueError('capacity and guard must be nonnegative')
    before = unique_pages(live, page_size)
    after = unique_pages(live + [candidate], page_size)
    delta = len(after - before)
    free = capacity_pages - len(before)
    return delta + guard_pages <= free, delta, free


def required_instances(rate, demand_per_request, capacity_per_instance):
    if rate < 0 or demand_per_request < 0 or capacity_per_instance <= 0:
        raise ValueError('invalid service inputs')
    if rate == 0 or demand_per_request == 0:
        return 0
    return int(ceil(rate * demand_per_request / capacity_per_instance))


def plan_instances(rate, resources):
    return max(required_instances(rate, demand, capacity)
               for demand, capacity in resources)


def fluid_backlog(segments, service_rate, initial=0.0):
    if service_rate < 0:
        raise ValueError('service rate must be nonnegative')
    q = float(initial)
    for arrival_rate, duration in segments:
        if arrival_rate < 0 or duration < 0:
            raise ValueError('invalid fluid segment')
        q = max(0.0, q + (arrival_rate - service_rate) * duration)
    return q


def stepped_backlog(segments, service_rate, step=0.01):
    if service_rate < 0 or step <= 0:
        raise ValueError('invalid stepped inputs')
    q = 0.0
    for arrival_rate, duration in segments:
        if arrival_rate < 0 or duration < 0:
            raise ValueError('invalid fluid segment')
        steps = int(round(duration / step))
        for _ in range(steps):
            q = max(0.0, q + (arrival_rate - service_rate) * step)
    return q


def reset_backlog(segments, service_rate):
    q = 0.0
    for arrival_rate, duration in segments:
        q = max(0.0, (arrival_rate - service_rate) * duration)
    return q


def main():
    print('scope: CPU arithmetic and event model only; no GPU, network, or SLO measurement')

    page_size = 4
    a = list('ABCDEFG')
    b = list('ABCDEFGH')
    c = list('ABCDEFG')
    assert pages_of([], page_size) == set()
    assert len(unique_pages([a, c], page_size)) == 2
    assert len(unique_pages([a, b], page_size)) == 3

    ok_b, delta_b, free_b = try_admit([a], b, 3, page_size, 0)
    assert ok_b and delta_b == 1 and free_b == 1
    naive = naive_page_sum([a, b], page_size)
    assert naive == 4 and naive > 3
    assert not (naive <= 3)
    print('page sharing: unique=', len(unique_pages([a, b], page_size)),
          'naive=', naive, 'reference_admit=', ok_b)

    ok_guard, _, free_guard = try_admit([a], b, 3, page_size, 1)
    assert not ok_guard and free_guard == 1
    print('guard boundary: no_guard=True guarded=', ok_guard)

    resources = [(1000, 2500), (100, 250), (512, 800)]
    n = plan_instances(4, resources)
    assert n == 3
    floor_n = max((4 * demand) // capacity for demand, capacity in resources)
    assert floor_n == 2
    assert 4 * 512 > 2 * 800
    no_net = resources[:2]
    assert plan_instances(4, no_net) == 2
    assert required_instances(10, 0, 0.1) == 0
    print('service bound: plan=', n, 'floor=', floor_n,
          'network_omitted=', plan_instances(4, no_net))

    segments = [(160.0, 2.0), (60.0, 1.0), (160.0, 2.0)]
    exact = fluid_backlog(segments, 100.0)
    stepped = stepped_backlog(segments, 100.0)
    assert abs(exact - 200.0) < 1e-9
    assert abs(stepped - 200.0) < 1e-6
    wrong = reset_backlog(segments, 100.0)
    assert abs(wrong - 120.0) < 1e-9 and abs(wrong - exact) > 1.0
    assert fluid_backlog([(50.0, 10.0)], 100.0) == 0.0
    print('backlog: exact=', exact, 'stepped=', round(stepped, 6),
          'reset_control=', wrong)
    print('all scoped checks passed')


if __name__ == '__main__':
    main()
